#define MAX_LEN 256
char output_buffer[MAX_LEN];

int custom_formatter(const char *fmt, ...) {
    va_list args;
    int result;

    // 1. Initialize argument list
    va_start(args, fmt);

    // 2. Use vsprintf: writes formatted data to string
    //    using the pre-initialized va_list
    result = vsprintf(output_buffer, fmt, args);

    // 3. Clean up argument list
    va_end(args);

    return result;
}

// Purpose: Allows indirect processing of variadic arguments.
// Example call: custom_formatter("ID %d is %s", 101, "valid");
